import React, { useEffect, useState } from "react";
import apiClient from "../api";
import useApiData from "../useApiData";

const Summary = ({ user }) => {
  const { data: holdings, isLoading, error } = useApiData("/allHoldings");
  const [funds, setFunds] = useState(null);
  const [fundsError, setFundsError] = useState("");

  useEffect(() => {
    const controller = new AbortController();
    apiClient
      .get("/funds", { signal: controller.signal })
      .then((response) => setFunds(response.data))
      .catch((requestError) => {
        if (requestError.code !== "ERR_CANCELED") {
          setFundsError(
            requestError.response?.data?.message || "Unable to load account funds"
          );
        }
      });

    return () => controller.abort();
  }, []);
  const totalInvestment = holdings.reduce(
    (total, holding) =>
      total + (Number(holding.avg) || 0) * (Number(holding.qty) || 0),
    0
  );
  const currentValue = holdings.reduce(
    (total, holding) =>
      total + (Number(holding.price) || 0) * (Number(holding.qty) || 0),
    0
  );
  const profitLoss = currentValue - totalInvestment;
  const profitLossPercentage =
    totalInvestment > 0 ? (profitLoss / totalInvestment) * 100 : 0;
  const formatCurrency = (value) =>
    new Intl.NumberFormat("en-IN", {
      style: "currency",
      currency: "INR",
      maximumFractionDigits: 2,
    }).format(value);

  return (
    <>
      <div className="username">
        <h6>Hi, {user.name}!</h6>
        <hr className="divider" />
      </div>

      <div className="section">
        <span>
          <p>Equity</p>
        </span>

        <div className="data">
          <div className="first">
            <h3>
              {funds
                ? formatCurrency(funds.cashBalance)
                : fundsError
                  ? "Unavailable"
                  : "Loading..."}
            </h3>
            <p>Margin available</p>
          </div>
          <hr />

          <div className="second">
            <p>
              Margins used <span>{formatCurrency(0)}</span>
            </p>
            <p>
              Opening balance{" "}
              <span>
                {funds ? formatCurrency(funds.openingBalance) : "Loading..."}
              </span>
            </p>
          </div>
        </div>
        <hr className="divider" />
      </div>

      <div className="section">
        <span>
          <p>Holdings ({holdings.length})</p>
        </span>

        <div className="data">
          <div className="first">
            <h3 className={profitLoss >= 0 ? "profit" : "loss"}>
              {isLoading ? "Loading..." : formatCurrency(profitLoss)}
              {!isLoading && <small> {profitLossPercentage.toFixed(2)}%</small>}
            </h3>
            <p>P&L</p>
          </div>
          <hr />

          <div className="second">
            <p>
              Current Value{" "}
              <span>{isLoading ? "Loading..." : formatCurrency(currentValue)}</span>
            </p>
            <p>
              Investment{" "}
              <span>
                {isLoading ? "Loading..." : formatCurrency(totalInvestment)}
              </span>
            </p>
          </div>
        </div>
        {(error || fundsError) && (
          <p role="alert">{error || fundsError}</p>
        )}
        <hr className="divider" />
      </div>
    </>
  );
};

export default Summary;
